// TH14 v1.00b Stage 2 mid-stage wave 2.
// Source frame 0 = st02.ecl.txt MainSub01:636; card frame 0 starts the 120-frame buffer.
// Dependency: MainSub01:636-648, MainSub01b:650-663, ECir00:8-43,
// ECir00_at:45-64, Phantom01:841-861.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// ECir00_at:etSprite(0, type20 color3); target laser is colour-only.
const LASER_COLOR: int = 3;

// ECir00_at:45-64. One Line per loop step; C lasers fanned by B from base angle.
// laserNew(0,0,128,0,14) with etSpeed(3,3): grows 3 px/f to 128, then travels.
// Line judgement is 0.8L from origin+0.1L, half-width 14/4 -> target width 7.
async sub ecir00_at(base: angle, step: angle, count: int) {
    var ox: fx = $self_x;
    var oy: fx = $self_y;
    var a: angle = base;
    var k: int = 0;
    while k < count {
        var h: int = laser(LASER_COLOR, ox, oy, a, 0fx, 7fx, 0, 9999, 0);
        lz_speed(h, 3fx, 102.4fx);
        a = a + step;
        k = k + 1;
    }
}

// ECir00:8-43. Five 100-frame cycles: aim-player lunge, 40-frame speed ramp to 0,
// optional laser burst 40 frames in, then 60-frame pause; afterwards leave upward.
async sub ecir00() {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24): circular radius 24*0.5
    set_hitbox(8fx);     // setHitbox(16,16): 16*0.5
    var rank: int = global(GVAR_RANK);
    var step: angle = 90deg;   // diffF: E/N = pi/2, H = pi/3, L = pi/5
    var count: int = 4;        // diffI: E/N = 4, H = 6, L = 10
    if rank == 2 { step = 60deg; count = 6; }
    if rank == 3 { step = 36deg; count = 10; }
    var a: angle = 90deg;      // %A = 1.570796
    var b: int = 0;
    while b < 5 {
        move_vel(0, aim_player(), 3fx, EASE_LINEAR);   // moveVel(ANGLE_PLAYER,3)
        move_speed(40, 0fx, EASE_QUAD_IN);             // moveSpeedTime(40,mode1,0)
        wait(40);
        // unless (DIFF != 0 || B%2 == 0) skip: Easy fires on even B only.
        if rank != 0 || (b % 2) == 0 {
            spawn ecir00_at(a, step, count);
        }
        wait(60);
        a = a + 45deg;   // %A += 0.785398
        b = b + 1;
    }
    wait(100);
    move_vel(0, 270deg, 4fx, EASE_LINEAR);   // moveVel(-pi/2, 4)
    loop { wait(1); }
}

// Phantom01:841-861. No firing; ABS drift down plus REL sine offset.
// moveEllipseRel(RANDRAD, 0.034906585, 40, 0, ABS_ANGLE, 0) with axis=90deg,
// ratio 0 gives a pure (40*cos theta, 0) offset, theta_start = RANDRAD.
async sub phantom01() {
    set_invuln(65535);
    set_hurtbox(14fx);   // setHurtbox(28,28)
    set_hitbox(8fx);     // setHitbox(16,16)
    var x0: fx = $self_x;
    var y: fx = $self_y;
    var theta: angle = rand(65536) as angle;
    var speed: fx = 1fx;
    var t: int = 0;
    move_to(0, x0 + 40fx * cos(theta), y, EASE_LINEAR);
    loop {
        if t < 120 {
            var u: fx = (t as fx) / 120fx;
            speed = 0.6fx + 0.4fx * (1fx - u * u * u * u);  // mode3 = t^4
            t = t + 1;
        }
        theta = theta + 2deg;   // omega 0.034906585 rad/frame
        y = y + speed;
        move_to(0, x0 + 40fx * cos(theta), y, EASE_LINEAR);
        wait(1);
    }
}

// MainSub01b:650-663. Four pairs, first at +60 frames then every 60.
async sub phantom_scheduler() {
    var i: int = 0;
    while i < 4 {
        wait(60);
        // Source draws one RANDF2 per create: 64+[-1,1]*64 and -64+[-1,1]*64.
        var r1: fx = (rand(65536) as fx) / 32768 - 1fx;
        var r2: fx = (rand(65536) as fx) / 32768 - 1fx;
        _ = spawn_enemy(64fx + r1 * 64fx, -24fx, 100, 0, 1000, 0, phantom01);
        _ = spawn_enemy(-64fx + r2 * 64fx, -24fx, 100, 0, 1000, 0, phantom01);
        i = i + 1;
    }
}

// MainSub01:636-648. Pair of ECir00 at 0, +120, +240; MainSub01b runs async.
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn phantom_scheduler();
    _ = spawn_enemy(-128fx, -24fx, 300, 0, 1000, 0, ecir00);
    _ = spawn_enemy(128fx, -24fx, 300, 0, 1000, 0, ecir00);
    wait(120);
    _ = spawn_enemy(-160fx, -24fx, 300, 0, 1000, 0, ecir00);
    _ = spawn_enemy(160fx, -24fx, 300, 0, 1000, 0, ecir00);
    wait(120);
    _ = spawn_enemy(-192fx, -24fx, 300, 0, 1000, 0, ecir00);
    _ = spawn_enemy(192fx, -24fx, 300, 0, 1000, 0, ecir00);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
